import ast
import pathlib
import sys

root = pathlib.Path(sys.argv[1])
found = 0
for path in sorted(root.rglob('*.py')):
    if any(part in ('.venv', '.claude', '__pycache__') for part in path.parts):
        continue
    tree = ast.parse(path.read_text())
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                name = (alias.asname or alias.name).split('.')[0]
                imported[name] = node.lineno
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    used |= {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    is_init = path.name == '__init__.py'
    for name, line in imported.items():
        if name not in used and not is_init and 'noqa' not in path.read_text().splitlines()[line - 1]:
            found += 1
            print(f'{path.relative_to(root)}:{line} unused import {name}')
print('unused imports:', found)

